// Contact annotations are independent of message capture and original names.
const crm={contacts:new Map(),results:null,query:'',generation:0,timer:null,editing:null};
const fold=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('ro');
async function crmRequest(path,body){const r=await fetch('/crm/'+path,{method:body?'POST':'GET',headers:{'X-Archive-Key':token,'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(20000)});const data=await r.json();if(!r.ok)throw Error(data.error||'Fișa de contact nu poate fi accesată.');return data}
const order=el('select','crm-sort');order.id='crm-order';order.setAttribute('aria-label','Ordinea conversațiilor');
for(const [value,label] of [['alpha','Nume: A → Z'],['recent','Cele mai recente mesaje'],['tag','Eticheta mea: A → Z']]){const option=el('option','',label);option.value=value;order.append(option)}
order.value=localStorage.getItem('alibaba-sort')||'alpha';
const databaseButton=el('button','crm-button','Baza de contacte');databaseButton.style.marginTop='10px';
document.querySelector('.sidehead').append(order,databaseButton);
const subtitle=el('button','crm-subtitle','Adaugă nume personalizat și etichete');$('name').parentElement.append(subtitle);
const editButton=el('button','crm-button','Fișă contact');document.querySelector('.actions').prepend(editButton);
const searchbar=el('div','crm-searchbar'),messageSearch=el('input'),messageHits=el('span');messageSearch.placeholder='Caută în conversația deschisă…';messageSearch.setAttribute('aria-label','Caută în mesajele conversației');searchbar.append(messageSearch,messageHits);$('notice').after(searchbar);
const dialog=el('dialog','crm-dialog');dialog.innerHTML='<h2 id="crm-heading">Fișă contact</h2><div id="crm-original" class="explain"></div><div id="crm-origin" class="explain"></div><form id="crm-form"><div class="crm-fields" id="crm-fields"></div><div class="crm-error" id="crm-error" role="status"></div><div class="crm-buttons"><button type="button" class="crm-button" id="crm-cancel">Închide</button><button class="crm-save" id="crm-save">Salvează modificările</button></div></form><div class="crm-facts" id="crm-facts"></div>';document.body.append(dialog);
const labels={alias:'Denumirea mea pentru conversație',category:'Categoria mea',tag:'Eticheta mea',company:'Firmă (verificată / completată de mine)',email:'E-mail verificat',phone:'Telefon / WhatsApp verificat',country:'Țară / localitate',website:'Site web verificat',notes:'Notițele mele'};
for(const [key,label] of Object.entries(labels)){const wrap=el('label',key==='notes'?'wide':'',label),input=el(key==='notes'?'textarea':'input');input.id='crm-'+key;input.maxLength=key==='notes'?5000:300;wrap.append(input);$('crm-fields').append(wrap)}
$('crm-cancel').onclick=()=>dialog.close();
const dbDialog=el('dialog','crm-dialog');dbDialog.innerHTML='<h2>Contacte și firme</h2><p class="explain">Numele Alibaba rămâne original. Datele personale completate de tine sunt păstrate separat. Selectează un contact pentru conversație și fișă.</p><input id="crm-db-search" placeholder="Caută nume, firmă, categorie, etichetă…" aria-label="Caută în contacte"><div id="crm-db-table"></div><div class="crm-buttons"><button type="button" class="crm-button" id="crm-db-close">Închide</button></div>';document.body.append(dbDialog);$('crm-db-close').onclick=()=>dbDialog.close();
function annotation(id){return crm.contacts.get(id)||{personal:{},source:{}}}
function sortedConversations(items,mode){return [...items].sort((a,b)=>{const ca=annotation(a.id),cb=annotation(b.id);if(mode==='recent'){const date=(cb.source.lastMessageAt||'').localeCompare(ca.source.lastMessageAt||'');if(date)return date}if(mode==='tag'){const ta=ca.personal.tag||'',tb=cb.personal.tag||'';if(!ta!==!tb)return ta?-1:1;const tag=ta.localeCompare(tb,'ro');if(tag)return tag}return (ca.personal.alias||a.contact).localeCompare(cb.personal.alias||b.contact,'ro')})}
drawList=function(){
 $('list').replaceChildren();const visible=sortedConversations(summaries,order.value).filter(d=>!crm.query||crm.results?.has(d.id));
 for(const d of visible){const c=annotation(d.id),p=c.personal,s=c.source,b=el('button','person'+(d.id===selected?' active':'')),t=el('div','detail');b.append(el('span','avatar',initials(d.contact)));t.append(el('strong','',d.contact));if(p.alias)t.append(el('div','crm-alias',p.alias));for(const tag of [p.category,p.tag,s.alibabaCategory?('Alibaba: '+s.alibabaCategory):''])if(tag)t.append(el('span','crm-tag',tag));const hit=crm.results?.get(d.id);t.append(el('div','preview',hit?.snippet||s.preview||d.preview||''));t.append(el('div','crm-date',s.lastMessageAt?('Ultimul mesaj: '+s.lastMessageAt.replace('T',' ')):'Dată mesaj necunoscută'));if(hit?.count)t.append(el('div','crm-date',hit.count+' mesaje găsite'));b.append(t);b.onclick=()=>{messageSearch.value=hit?.count?crm.query:'';select(d.id).catch(showError)};$('list').append(b)}
 if(!visible.length)$('list').append(el('div','sidehead',crm.query&&crm.results===null?'Se caută în arhivă…':'Nicio conversație găsită.'));
};
order.onchange=()=>{localStorage.setItem('alibaba-sort',order.value);drawList()};
function updateSubtitle(){const c=annotation(selected);subtitle.textContent=c.personal.alias||'Adaugă nume personalizat și etichete';subtitle.title=[c.personal.category,c.personal.tag].filter(Boolean).join(' · ')}
const originalSelect=select;
select=async function(id,refresh=false){await originalSelect(id,refresh);if(selected!==id)return;updateSubtitle();filterMessages()};
function highlightText(node,text,q){node.replaceChildren();const f=fold(text),needle=fold(q);let offset=0,position;if(!needle){node.append(document.createTextNode(text));return}while((position=f.indexOf(needle,offset))!==-1){node.append(document.createTextNode(text.slice(offset,position)),el('mark','',text.slice(position,position+needle.length)));offset=position+needle.length}node.append(document.createTextNode(text.slice(offset)))}
function filterMessages(){const d=cache.get(selected);if(!d)return;const q=messageSearch.value.trim();let hits=0;for(const row of $('messages').querySelectorAll('.row')){const m=d.messages.find(m=>m.key===row.dataset.messageKey);if(!m)continue;const match=!q||fold(m.text).includes(fold(q));row.hidden=!match;if(match)hits++;const body=row.querySelector('.message-text');if(body)highlightText(body,m.text||'',q)}messageHits.textContent=q?hits+' mesaje găsite':d.messages.length+' mesaje';}
messageSearch.oninput=filterMessages;
async function searchAll(){const generation=++crm.generation;crm.query=$('search').value.trim();if(!crm.query){crm.results=null;drawList();return}crm.results=null;drawList();try{const r=await crmRequest('search?q='+encodeURIComponent(crm.query));if(generation!==crm.generation)return;crm.results=new Map(r.results.map(d=>[d.id,d]));drawList()}catch(e){if(generation===crm.generation)showError(e)}}
$('search').oninput=()=>{clearTimeout(crm.timer);crm.generation++;crm.timer=setTimeout(searchAll,250)};
async function refreshContacts(){try{const r=await crmRequest('contacts');crm.contacts=new Map(r.contacts.map(c=>[c.id,c]));drawList();updateSubtitle();if(r.errors?.length)$('notice').textContent='Unele fișe nu au putut fi actualizate: '+r.errors.length+'. Datele anterioare sunt păstrate.';if(crm.query)await searchAll()}catch(e){showError(e)}}
async function editContact(){if(!selected)return;try{const c=await crmRequest('contact/'+encodeURIComponent(selected));crm.editing=c.id;$('crm-heading').textContent='Fișă contact · '+c.original;$('crm-original').textContent='Participant Alibaba: '+c.original+' · ID '+c.id;$('crm-origin').textContent='Categoria Alibaba: '+(c.source.alibabaCategory||'Nu este disponibilă în datele capturate')+' | Firma Alibaba: '+(c.source.company||'Nedisponibilă')+(c.source.profileSource?' | Sursa: '+c.source.profileSource:'');for(const key of Object.keys(labels))$('crm-'+key).value=c.personal[key]||'';$('crm-error').textContent='';$('crm-facts').replaceChildren(el('strong','','Date găsite în mesaje — verifică titularul înainte de preluare'));for(const fact of c.source.facts||[]){const row=el('div','crm-fact',fact.field+': '+fact.value),use=el('button','crm-button','Preia în fișă');use.type='button';use.onclick=()=>$('crm-'+fact.field).value=fact.value;row.append(use,el('blockquote','',fact.excerpt+' (expeditor: '+(fact.sender==='partner'?c.original:'necunoscut')+')'));$('crm-facts').append(row)}if(!c.source.facts?.length)$('crm-facts').append(el('p','','Nu au fost identificate date de contact în mesajele salvate.'));dialog.showModal()}catch(e){showError(e)}}
editButton.onclick=editContact;subtitle.onclick=editContact;
$('crm-form').onsubmit=async e=>{e.preventDefault();const id=crm.editing;if(!id)return;$('crm-save').disabled=true;$('crm-error').textContent='Se salvează…';try{const values=Object.fromEntries(Object.keys(labels).map(k=>[k,$('crm-'+k).value]));const c=await crmRequest('contact/'+encodeURIComponent(id),values);crm.contacts.set(c.id,c);dialog.close();drawList();updateSubtitle();if(crm.query)await searchAll()}catch(e){$('crm-error').textContent=e.message}finally{$('crm-save').disabled=false}};
function drawContacts(){const q=fold($('crm-db-search').value),table=el('table','crm-table'),head=el('tr');for(const name of ['Participant / denumirea mea','Firmă','Categorie / etichetă','E-mail / telefon'])head.append(el('th','',name));table.append(head);for(const c of [...crm.contacts.values()].sort((a,b)=>a.original.localeCompare(b.original,'ro'))){if(q&&!fold(c.original+' '+JSON.stringify(c.personal)+' '+c.source.company+' '+c.source.alibabaCategory).includes(q))continue;const row=el('tr'),cell=el('td'),button=el('button','',c.original+(c.personal.alias?' / '+c.personal.alias:''));button.onclick=async()=>{dbDialog.close();messageSearch.value='';await select(c.id);await editContact()};cell.append(button);row.append(cell,el('td','',c.personal.company||c.source.company||'—'),el('td','',[c.personal.category,c.personal.tag,c.source.alibabaCategory].filter(Boolean).join(' / ')||'—'),el('td','',[c.personal.email,c.personal.phone].filter(Boolean).join(' / ')||'—'));table.append(row)}$('crm-db-table').replaceChildren(table)}
$('crm-db-search').oninput=drawContacts;databaseButton.onclick=()=>{drawContacts();dbDialog.showModal()};
refreshContacts();setInterval(refreshContacts,15000);
